let deliveredIds = ACSEmailStatusUpdateOperational
| where TimeGenerated {TimeRange}
| where isnotempty(RecipientId)
| where DeliveryStatus == "Delivered"
| extend Clinic = strcat(SenderUsername, "@", SenderDomain)
| where ('value::all' in ({ClinicFilter})) or (Clinic in ({ClinicFilter}))
| distinct InternetMessageId;
let statusScoped = ACSEmailStatusUpdateOperational
| where TimeGenerated {TimeRange}
| where isnotempty(RecipientId)
| extend Clinic = strcat(SenderUsername, "@", SenderDomain)
| where ('value::all' in ({ClinicFilter})) or (Clinic in ({ClinicFilter}));
let delivered = toscalar(statusScoped | where DeliveryStatus == "Delivered" | summarize dcount(InternetMessageId));
let failedBounced = toscalar(statusScoped | where DeliveryStatus in ("Bounced", "Failed") | summarize dcount(InternetMessageId));
let suppressed = toscalar(statusScoped | where DeliveryStatus in ("Suppressed", "Quarantined") | summarize dcount(InternetMessageId));
let viewed = toscalar(ACSEmailUserEngagementOperational | where TimeGenerated {TimeRange} | where EngagementType == "View" | where InternetMessageId in (deliveredIds) | summarize dcount(InternetMessageId));
let clicked = toscalar(ACSEmailUserEngagementOperational | where TimeGenerated {TimeRange} | where EngagementType == "Click" | where InternetMessageId in (deliveredIds) | summarize dcount(InternetMessageId));
print Metric = pack_array("Delivered", "Failed / Bounced", "Suppressed / Quarantined", "Viewed / Opened", "Clicked"), Count = pack_array(delivered, failedBounced, suppressed, viewed, clicked)
| mv-expand Metric to typeof(string), Count to typeof(long)

let deliveredIds = ACSEmailStatusUpdateOperational
| where TimeGenerated {TimeRange}
| where isnotempty(RecipientId)
| where DeliveryStatus == "Delivered"
| extend Clinic = strcat(SenderUsername, "@", SenderDomain)
| where ('value::all' in ({ClinicFilter})) or (Clinic in ({ClinicFilter}))
| distinct InternetMessageId;
let deliveredCount = toscalar(deliveredIds | summarize count());
let engagementRows = ACSEmailUserEngagementOperational
| where TimeGenerated {TimeRange}
| where InternetMessageId in (deliveredIds)
| summarize Count = dcount(InternetMessageId) by EngagementType
| project Label = case(EngagementType == "View", "Viewed / Opened", EngagementType), ClickValue = EngagementType, Count;
let totalRow = print Label = "Delivered (Total) - click to reset", ClickValue = "value::all", Count = deliveredCount;
totalRow
| union engagementRows
| order by iff(Label == "Delivered (Total) - click to reset", 0, 1) asc, Count desc
